WITH filtered AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, DATEDIFF(CURRENT_DATE(), starts_on) / 365 AS years_since_starts_on, COALESCE(channel, 'N/A') AS channel_clean FROM promotions WHERE channel != 'partner') SELECT * FROM (SELECT id, promo_code, years_since_starts_on, discount_pct FROM filtered) src UNPIVOT (metric_value FOR kpi IN (years_since_starts_on AS YEARS_SINCE_STARTS_ON_VAL, discount_pct AS DISCOUNT_PCT));
